/* Balsa UI public design-theme contract. Import after balsa-foundation.css. */

@theme inline {
  --font-balsa-title: var(--balsa-font-title);
  --font-balsa-body: var(--balsa-font-body);
  --radius-balsa-control: var(--balsa-radius-control);
  --radius-balsa-surface: var(--balsa-radius-surface);
  --radius-balsa-panel: var(--balsa-radius-panel);
  /* The pill radius badges, toggles, and pill-shaped controls share. It is a
     recipe value, not a constant: a square shape recipe collapses it to 0 so a
     pill control squares off with everything around it. */
  --radius-balsa-pill: var(--balsa-radius-badge);
  --spacing-balsa-control-inline: var(--balsa-spacing-control-inline);
  --spacing-balsa-density-compact: var(--balsa-spacing-density-compact);
  --spacing-balsa-density-default: var(--balsa-spacing-density-default);
  --spacing-balsa-density-comfortable: var(--balsa-spacing-density-comfortable);
  /* The spacing scale, aliased so `gap-balsa-md` and `py-balsa-section-lg` read as
     what they are. See docs/spacing-scale.md for the steps, their roles and the
     three laws that derive everything not on the scale. */
  --spacing-balsa-4xs: var(--balsa-space-4xs);
  --spacing-balsa-3xs: var(--balsa-space-3xs);
  --spacing-balsa-2xs: var(--balsa-space-2xs);
  --spacing-balsa-xs: var(--balsa-space-xs);
  --spacing-balsa-sm: var(--balsa-space-sm);
  --spacing-balsa-md: var(--balsa-space-md);
  --spacing-balsa-lg: var(--balsa-space-lg);
  --spacing-balsa-xl: var(--balsa-space-xl);
  --spacing-balsa-2xl: var(--balsa-space-2xl);
  --spacing-balsa-3xl: var(--balsa-space-3xl);
  --spacing-balsa-section-sm: var(--balsa-space-section-sm);
  --spacing-balsa-section-md: var(--balsa-space-section-md);
  --spacing-balsa-section-lg: var(--balsa-space-section-lg);
  --shadow-balsa-control: var(--balsa-shadow-control);
  --shadow-balsa-surface: var(--balsa-shadow-surface);
  --shadow-balsa-panel: var(--balsa-shadow-panel);
  --shadow-balsa-sm: var(--balsa-shadow-sm);
  --shadow-balsa-md: var(--balsa-shadow-md);
  --shadow-balsa-lg: var(--balsa-shadow-lg);
  --shadow-balsa-detail: var(--balsa-shadow-detail);
  /* Motion as utilities. Without these there was no way to write a
     token-driven duration as a class, which is why components reached for
     `duration-200` and pinned themselves to one speed at every motion
     setting -- including the one that asks for none. */
  --transition-duration-balsa-fast: var(--balsa-motion-fast);
  --transition-duration-balsa-normal: var(--balsa-motion-normal);
  --transition-duration-balsa-slow: var(--balsa-motion-slow);
  --ease-balsa: var(--balsa-motion-easing);
}

/* ---------------------------------------------------------------------------
   The spacing scale.

   Every step is a multiple of one base unit, so the unit is the only number
   here that was chosen — the rest follow from it, and changing it rescales the
   whole system rather than requiring eleven edits.

   Two scales, because spacing answers two different questions. `space` is the
   rhythm between siblings and inside a component; `space-section` is the
   distance between page regions, which the website has been improvising with
   ad-hoc values because it had nothing to draw on. They deliberately do not
   overlap: rhythm tops out at 32px and section starts at 48px.

   A control's own inset is neither. It is derived from the control's size and
   the spacing density, so nobody picks one — see docs/spacing-scale.md.

   Declared on :root rather than inside a theme preset: a preset may override
   any of it, but the scale exists before any preset does.
   --------------------------------------------------------------------------- */
:root {
  --balsa-space-unit: 0.25rem;

  /* The fine region is a uniform half-unit ladder: 2, 4, 6, 8, 10, 12. It is
     where a control is built, and every rung of it is in use. The coarse region
     steps by a full unit and then doubles, because layout distances stop
     needing 2px discrimination. */
  --balsa-space-0: 0px;
  --balsa-space-4xs: calc(var(--balsa-space-unit) * 0.5);
  --balsa-space-3xs: calc(var(--balsa-space-unit) * 1);
  --balsa-space-2xs: calc(var(--balsa-space-unit) * 1.5);
  --balsa-space-xs: calc(var(--balsa-space-unit) * 2);
  --balsa-space-sm: calc(var(--balsa-space-unit) * 2.5);
  --balsa-space-md: calc(var(--balsa-space-unit) * 3);
  --balsa-space-lg: calc(var(--balsa-space-unit) * 4);
  --balsa-space-xl: calc(var(--balsa-space-unit) * 5);
  --balsa-space-2xl: calc(var(--balsa-space-unit) * 6);
  --balsa-space-3xl: calc(var(--balsa-space-unit) * 8);

  --balsa-space-section-sm: calc(var(--balsa-space-unit) * 12);
  --balsa-space-section-md: calc(var(--balsa-space-unit) * 16);
  --balsa-space-section-lg: calc(var(--balsa-space-unit) * 20);

  /* A control's own inset, by its size. Deliberately its own scale rather than
     a rhythm step: rhythm is the distance between two things, and this is the
     distance from a control's edge to what it contains. Nobody picks one -- a
     caller picks a size. */
  --balsa-inset-sm: calc(var(--balsa-space-unit) * 3);
  --balsa-inset-md: calc(var(--balsa-space-unit) * 4);
  --balsa-inset-lg: calc(var(--balsa-space-unit) * 6);
  --balsa-inset-xl: calc(var(--balsa-space-unit) * 8);
  --balsa-inset-2xl: calc(var(--balsa-space-unit) * 10);
}

:root,
[data-theme="modern-flat"],
[data-theme-base="modern-flat"] {
  --balsa-font-title: "Space Grotesk", sans-serif;
  --balsa-font-body: "Noto Sans", sans-serif;
  --balsa-title-letter-spacing: 0px;
  --balsa-title-text-transform: none;
  --balsa-radius-control: 0.5rem;
  --balsa-code-control-radius: 0.5rem;
  --balsa-radius-surface: 0.875rem;
  --balsa-radius-panel: 1.125rem;
  --balsa-radius-badge: 9999px;
  --balsa-radius-toggle: 9999px;
  --balsa-spacing-control-inline: 0.75rem;
  --balsa-spacing-density-compact: 0.25rem;
  --balsa-spacing-density-default: 0.5rem;
  --balsa-spacing-density-comfortable: 0.75rem;
  --balsa-border-width: 1px;
  --balsa-outline-border-width: 1px;
  --balsa-solid-border-width: 1px;
  --balsa-border-opacity: 55%;
  --balsa-border-style: solid;
  --balsa-shadow-sm: none;
  --balsa-shadow-md: none;
  --balsa-shadow-lg: none;
  --balsa-shadow-detail: none;
  --balsa-shadow-control: var(--balsa-shadow-sm);
  --balsa-shadow-surface: var(--balsa-shadow-md);
  --balsa-shadow-panel: var(--balsa-shadow-lg);
  --balsa-shadow-playground: none;
  --balsa-motion-fast: 160ms;
  --balsa-motion-normal: 260ms;
  --balsa-motion-slow: 420ms;
  --balsa-motion-easing: cubic-bezier(0.2, 0.8, 0.2, 1);
  --balsa-control-hover-transform: translateY(-1px);
  --balsa-control-active-transform: translateY(0);
  --balsa-surface-hover-transform: none;
  --balsa-control-text-transform: none;
  --balsa-control-letter-spacing: 0;
  --balsa-control-font-family: var(--balsa-font-body);
  --balsa-control-font-weight: 600;
  --balsa-backdrop-blur: 0px;
  --balsa-backdrop-saturation: 1;
  --balsa-backdrop-filter: none;
  --balsa-backdrop-filter-contained: none;
  --balsa-overlay-blur: 4px;
  --balsa-overlay-filter: blur(4px);
  --balsa-material-background: var(--balsa-color-background);
  --balsa-material-foreground: var(--balsa-color-foreground);
  --balsa-material-surface: var(--balsa-color-surface);
  --balsa-material-surface-foreground: var(--balsa-color-surface-foreground);
  --balsa-material-surface-elevated: var(--balsa-color-surface-elevated);
  --balsa-material-surface-elevated-foreground: var(--balsa-color-surface-elevated-foreground);
  --balsa-material-muted: var(--balsa-color-muted);
  --balsa-material-muted-foreground: var(--balsa-color-muted-foreground);
  --balsa-material-inverse: var(--balsa-color-inverse);
  --balsa-material-inverse-foreground: var(--balsa-color-inverse-foreground);
  --balsa-material-primary: var(--balsa-color-primary);
  --balsa-material-primary-foreground: var(--balsa-color-primary-foreground);
  --balsa-material-primary-hover: var(--balsa-color-primary-hover);
  --balsa-material-primary-active: var(--balsa-color-primary-active);
  --balsa-material-secondary: var(--balsa-color-secondary);
  --balsa-material-secondary-foreground: var(--balsa-color-secondary-foreground);
  --balsa-material-secondary-hover: var(--balsa-color-secondary-hover);
  --balsa-material-secondary-active: var(--balsa-color-secondary-active);
  --balsa-material-accent: var(--balsa-color-accent);
  --balsa-material-accent-foreground: var(--balsa-color-accent-foreground);
  --balsa-material-accent-hover: var(--balsa-color-accent-hover);
  --balsa-material-accent-active: var(--balsa-color-accent-active);
  --balsa-material-input: var(--balsa-color-input);
  --balsa-material-input-border: var(--balsa-color-input-border);
  --balsa-material-selected: var(--balsa-color-selected);
  --balsa-material-border: var(--balsa-color-border);
  --balsa-material-border-strong: var(--balsa-color-border-strong);
  --balsa-material-code: var(--balsa-color-code);
  --balsa-material-slider-thumb: var(--balsa-color-input);
  --balsa-material-playground-workspace: var(--balsa-material-muted);
  --balsa-material-playground-properties: var(--balsa-material-surface);
  --balsa-material-outline-control: transparent;
  --balsa-material-outline-control-hover: color-mix(in oklab, currentColor 15%, transparent);
  --balsa-material-outline-control-active: color-mix(in oklab, currentColor 25%, transparent);
  --balsa-material-outline-control-border: currentColor;
  --balsa-material-glass-control: color-mix(in oklab, var(--balsa-color-surface-elevated) 78%, currentColor 3%);
  --balsa-material-glass-control-hover: color-mix(in oklab, var(--balsa-color-surface-elevated) 80%, currentColor 8%);
  --balsa-material-glass-control-active: color-mix(in oklab, var(--balsa-color-surface-elevated) 82%, currentColor 12%);
  --balsa-material-glass-control-border: color-mix(in oklab, currentColor 18%, transparent);
}

[data-theme="brutalism"],
[data-theme-base="brutalism"] {
  --balsa-font-title: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --balsa-font-body: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --balsa-title-letter-spacing: -0.03em;
  --balsa-title-text-transform: uppercase;
  --balsa-radius-control: 0px;
  --balsa-code-control-radius: 0px;
  --balsa-radius-surface: 0px;
  --balsa-radius-panel: 0px;
  --balsa-radius-badge: 0px;
  --balsa-radius-toggle: 0px;
  --balsa-spacing-control-inline: 0.75rem;
  --balsa-spacing-density-compact: 0.25rem;
  --balsa-spacing-density-default: 0.5rem;
  --balsa-spacing-density-comfortable: 0.75rem;
  --balsa-border-width: 2px;
  --balsa-outline-border-width: 2px;
  --balsa-solid-border-width: 2px;
  --balsa-border-opacity: 100%;
  --balsa-border-style: solid;
  --balsa-shadow-sm: none;
  --balsa-shadow-md: none;
  --balsa-shadow-lg: none;
  --balsa-shadow-detail: none;
  --balsa-shadow-control: var(--balsa-shadow-sm);
  --balsa-shadow-surface: var(--balsa-shadow-md);
  --balsa-shadow-panel: var(--balsa-shadow-lg);
  --balsa-shadow-playground: var(--balsa-shadow-panel);
  --balsa-motion-fast: 90ms;
  --balsa-motion-normal: 140ms;
  --balsa-motion-slow: 220ms;
  --balsa-motion-easing: linear;
  --balsa-control-hover-transform: translate(-2px, -2px);
  --balsa-control-active-transform: translate(1px, 1px);
  --balsa-surface-hover-transform: translate(-2px, -2px);
  --balsa-control-text-transform: uppercase;
  --balsa-control-letter-spacing: 0.06em;
  --balsa-control-font-family: var(--balsa-font-body);
  --balsa-control-font-weight: 800;
  --balsa-backdrop-blur: 0px;
  --balsa-backdrop-saturation: 1;
  --balsa-backdrop-filter: none;
  --balsa-backdrop-filter-contained: none;
  --balsa-overlay-blur: 0px;
  --balsa-overlay-filter: none;
  --balsa-material-background: var(--balsa-color-background);
  --balsa-material-foreground: var(--balsa-color-foreground);
  --balsa-material-surface: var(--balsa-color-background);
  --balsa-material-surface-foreground: var(--balsa-color-foreground);
  --balsa-material-surface-elevated: var(--balsa-color-background);
  --balsa-material-surface-elevated-foreground: var(--balsa-color-foreground);
  --balsa-material-muted: color-mix(in oklab, var(--balsa-color-background) 88%, var(--balsa-color-foreground));
  --balsa-material-muted-foreground: var(--balsa-color-muted-foreground);
  --balsa-material-inverse: var(--balsa-color-inverse);
  --balsa-material-inverse-foreground: var(--balsa-color-inverse-foreground);
  --balsa-material-primary: var(--balsa-color-primary);
  --balsa-material-primary-foreground: var(--balsa-color-primary-foreground);
  --balsa-material-primary-hover: var(--balsa-color-primary-hover);
  --balsa-material-primary-active: var(--balsa-color-primary-active);
  --balsa-material-secondary: var(--balsa-color-secondary);
  --balsa-material-secondary-foreground: var(--balsa-color-secondary-foreground);
  --balsa-material-secondary-hover: var(--balsa-color-secondary-hover);
  --balsa-material-secondary-active: var(--balsa-color-secondary-active);
  --balsa-material-accent: var(--balsa-color-accent);
  --balsa-material-accent-foreground: var(--balsa-color-accent-foreground);
  --balsa-material-accent-hover: var(--balsa-color-accent-hover);
  --balsa-material-accent-active: var(--balsa-color-accent-active);
  --balsa-material-input: var(--balsa-color-background);
  --balsa-material-input-border: var(--balsa-color-input-border);
  --balsa-material-selected: var(--balsa-color-selected);
  --balsa-material-border: var(--balsa-color-border);
  --balsa-material-border-strong: var(--balsa-color-border-strong);
  --balsa-material-code: var(--balsa-color-code);
  --balsa-material-slider-thumb: var(--balsa-color-input);
  --balsa-material-playground-workspace: var(--balsa-material-muted);
  --balsa-material-playground-properties: var(--balsa-material-surface);
  --balsa-material-outline-control: transparent;
  --balsa-material-outline-control-hover: color-mix(in oklab, currentColor 15%, transparent);
  --balsa-material-outline-control-active: color-mix(in oklab, currentColor 25%, transparent);
  --balsa-material-outline-control-border: currentColor;
  --balsa-material-glass-control: color-mix(in oklab, var(--balsa-color-background) 78%, currentColor 3%);
  --balsa-material-glass-control-hover: color-mix(in oklab, var(--balsa-color-background) 80%, currentColor 8%);
  --balsa-material-glass-control-active: color-mix(in oklab, var(--balsa-color-background) 82%, currentColor 12%);
  --balsa-material-glass-control-border: color-mix(in oklab, currentColor 18%, transparent);
}

[data-theme="glassmorphism"],
[data-theme-base="glassmorphism"] {
  --balsa-font-title: "Space Grotesk", sans-serif;
  --balsa-font-body: "Noto Sans", sans-serif;
  --balsa-title-letter-spacing: 0px;
  --balsa-title-text-transform: none;
  --balsa-radius-control: 0.75rem;
  --balsa-code-control-radius: 0.5rem;
  --balsa-radius-surface: 1.125rem;
  --balsa-radius-panel: 1.5rem;
  --balsa-radius-badge: 9999px;
  --balsa-radius-toggle: 9999px;
  --balsa-spacing-control-inline: 0.75rem;
  --balsa-spacing-density-compact: 0.25rem;
  --balsa-spacing-density-default: 0.5rem;
  --balsa-spacing-density-comfortable: 0.75rem;
  --balsa-border-width: 1px;
  --balsa-outline-border-width: 1px;
  --balsa-solid-border-width: 1px;
  --balsa-border-opacity: 100%;
  --balsa-border-style: solid;
  --balsa-shadow-sm: 0 6px 20px color-mix(in oklab, var(--balsa-color-foreground) 4%, transparent);
  --balsa-shadow-md: 0 14px 36px color-mix(in oklab, var(--balsa-color-foreground) 5%, transparent);
  --balsa-shadow-lg: 0 8px 24px color-mix(in oklab, var(--balsa-color-foreground) 5%, transparent);
  --balsa-shadow-detail: 0 1px 2px color-mix(in oklab, var(--balsa-color-foreground) 8%, transparent);
  --balsa-shadow-control: var(--balsa-shadow-sm);
  --balsa-shadow-surface: var(--balsa-shadow-md);
  --balsa-shadow-panel: var(--balsa-shadow-lg);
  --balsa-shadow-playground: 0 12px 32px color-mix(in oklab, var(--balsa-color-foreground) 4%, transparent);
  --balsa-motion-fast: 180ms;
  --balsa-motion-normal: 320ms;
  --balsa-motion-slow: 520ms;
  --balsa-motion-easing: cubic-bezier(0.22, 1, 0.36, 1);
  --balsa-control-hover-transform: translateY(-1px) scale(1.01);
  --balsa-control-active-transform: scale(0.98);
  --balsa-surface-hover-transform: none;
  --balsa-control-text-transform: none;
  --balsa-control-letter-spacing: 0;
  --balsa-control-font-family: var(--balsa-font-body);
  --balsa-control-font-weight: 600;
  --balsa-backdrop-blur: 14px;
  --balsa-backdrop-saturation: 1.1;
  --balsa-backdrop-filter: blur(14px) saturate(1.1);
  /* A glass surface inside another blurs less; see theme.ts. */
  --balsa-backdrop-filter-contained: blur(10px) saturate(1.1);
  --balsa-overlay-blur: 4px;
  --balsa-overlay-filter: blur(4px);
  --balsa-material-background: var(--balsa-color-background);
  --balsa-material-foreground: var(--balsa-color-foreground);
  --balsa-material-surface: color-mix(in oklab, var(--balsa-color-surface) 60%, transparent);
  --balsa-material-surface-foreground: var(--balsa-color-surface-foreground);
  --balsa-material-surface-elevated: color-mix(in oklab, var(--balsa-color-surface-elevated) 64%, transparent);
  --balsa-material-surface-elevated-foreground: var(--balsa-color-surface-elevated-foreground);
  --balsa-material-muted: color-mix(in oklab, var(--balsa-color-muted) 60%, transparent);
  --balsa-material-muted-foreground: var(--balsa-color-muted-foreground);
  --balsa-material-inverse: color-mix(in oklab, var(--balsa-color-inverse) 88%, transparent);
  --balsa-material-inverse-foreground: var(--balsa-color-inverse-foreground);
  --balsa-material-primary: var(--balsa-color-primary);
  --balsa-material-primary-foreground: var(--balsa-color-primary-foreground);
  --balsa-material-primary-hover: var(--balsa-color-primary-hover);
  --balsa-material-primary-active: var(--balsa-color-primary-active);
  --balsa-material-secondary: color-mix(in oklab, var(--balsa-color-secondary) 92%, transparent);
  --balsa-material-secondary-foreground: var(--balsa-color-secondary-foreground);
  --balsa-material-secondary-hover: color-mix(in oklab, var(--balsa-color-secondary-hover) 94%, transparent);
  --balsa-material-secondary-active: color-mix(in oklab, var(--balsa-color-secondary-active) 96%, transparent);
  --balsa-material-accent: color-mix(in oklab, var(--balsa-color-accent) 92%, transparent);
  --balsa-material-accent-foreground: var(--balsa-color-accent-foreground);
  --balsa-material-accent-hover: color-mix(in oklab, var(--balsa-color-accent-hover) 94%, transparent);
  --balsa-material-accent-active: color-mix(in oklab, var(--balsa-color-accent-active) 96%, transparent);
  --balsa-material-input: color-mix(in oklab, var(--balsa-color-input) 76%, transparent);
  --balsa-material-input-border: color-mix(in oklab, var(--balsa-color-foreground) 24%, transparent);
  --balsa-material-selected: color-mix(in oklab, var(--balsa-color-selected) 88%, transparent);
  --balsa-material-border: color-mix(in oklab, var(--balsa-color-foreground) 14%, transparent);
  --balsa-material-border-strong: color-mix(in oklab, var(--balsa-color-foreground) 22%, transparent);
  --balsa-material-code: color-mix(in oklab, var(--balsa-color-code) 88%, transparent);
  --balsa-material-slider-thumb: color-mix(in oklab, var(--balsa-color-input) 94%, var(--balsa-color-background));
  --balsa-material-playground-workspace: color-mix(in oklab, var(--balsa-color-muted) 32%, transparent);
  --balsa-material-playground-properties: color-mix(in oklab, var(--balsa-color-surface) 40%, transparent);
  --balsa-material-outline-control: color-mix(in oklab, var(--balsa-material-surface-elevated) 94%, currentColor 6%);
  --balsa-material-outline-control-hover: color-mix(in oklab, var(--balsa-material-surface-elevated) 86%, currentColor 14%);
  --balsa-material-outline-control-active: color-mix(in oklab, var(--balsa-material-surface-elevated) 78%, currentColor 22%);
  --balsa-material-outline-control-border: color-mix(in oklab, currentColor 32%, transparent);
  --balsa-material-glass-control: color-mix(in oklab, var(--balsa-color-surface) 50%, currentColor 4%);
  --balsa-material-glass-control-hover: color-mix(in oklab, var(--balsa-color-surface) 58%, currentColor 8%);
  --balsa-material-glass-control-active: color-mix(in oklab, var(--balsa-color-surface) 64%, currentColor 12%);
  --balsa-material-glass-control-border: color-mix(in oklab, currentColor 16%, transparent);
}

/* Stable component recipes. Components provide data hooks; themes provide values.
   Keeping recipes in the components layer lets consumer utilities make deliberate
   local adjustments without specificity escalation. */
@layer components {
:where([data-balsa]) {
  transition-duration: var(--balsa-motion-fast);
  transition-timing-function: var(--balsa-motion-easing);
}

:where([data-balsa="button"], [data-balsa="link"], [data-balsa-control]) {
  border-radius: var(--balsa-radius-control);
  border-style: var(--balsa-border-style);
  font-family: var(--balsa-control-font-family);
  font-weight: var(--balsa-control-font-weight);
  letter-spacing: var(--balsa-control-letter-spacing);
  text-transform: var(--balsa-control-text-transform);
  transition-duration: var(--balsa-motion-fast);
  transition-timing-function: var(--balsa-motion-easing);
}

/* ---------------------------------------------------------------------------
   Icon adjacency.

   An inset beside an icon is one base unit less than the same inset beside
   text, because an icon carries less optical weight than a word and the same
   gap reads wider next to it.

   This was already true and written out as a five-by-four table of literal
   padding classes, where the law was visible only to someone who compared the
   numbers. Stating it once removes the table, and removes 28px, 36px and 14px
   from the vocabulary: they were never chosen, only arrived at.

   Logical properties, so the reduction follows the writing direction. The old
   table used `pl`/`pr` and put the icon's smaller inset on the wrong side in
   RTL.
   --------------------------------------------------------------------------- */
[data-balsa="button"][data-size="sm"] { --balsa-inset: var(--balsa-inset-sm); }
[data-balsa="button"][data-size="md"] { --balsa-inset: var(--balsa-inset-md); }
[data-balsa="button"][data-size="lg"] { --balsa-inset: var(--balsa-inset-lg); }
[data-balsa="button"][data-size="xl"] { --balsa-inset: var(--balsa-inset-xl); }
[data-balsa="button"][data-size="2xl"] { --balsa-inset: var(--balsa-inset-2xl); }

/* Only where a size was resolved. A button told `:size="null"` opts out of the
   size scale entirely and carries whatever padding its caller gave it. */
[data-balsa="button"][data-size] {
  --balsa-inset-icon: max(0px, calc(var(--balsa-inset) - var(--balsa-space-unit)));
  padding-inline: var(--balsa-inset);
}

[data-balsa="button"][data-size][data-icon="prefix"] {
  padding-inline-start: var(--balsa-inset-icon);
}

[data-balsa="button"][data-size][data-icon="suffix"] {
  padding-inline-end: var(--balsa-inset-icon);
}

[data-balsa="button"][data-size][data-icon="both"] {
  padding-inline: var(--balsa-inset-icon);
}

/* A FAB is a circle sized by its height; an inset would make it an oval. */
[data-balsa="button"][data-shape="fab"] {
  padding-inline: 0;
}

:where([data-balsa="button"], [data-balsa="link"])[data-variant="solid"] {
  border-width: var(--balsa-solid-border-width);
  box-shadow: var(--balsa-shadow-control);
}

:where([data-balsa="button"], [data-balsa="link"])[data-variant="solid"]:not(:disabled) {
  border-color: color-mix(in oklab, currentColor var(--balsa-border-opacity, 100%), transparent);
}

:where([data-balsa="button"], [data-balsa="link"])[data-variant="outline"] {
  border-width: var(--balsa-outline-border-width);
  box-shadow: var(--balsa-shadow-control);
}

/* Glass buttons keep their material rim quieter than outline actions while
   retaining the selected semantic color for text and interaction tint. */
:where([data-balsa="button"])[data-variant="glass"] {
  border-width: var(--balsa-border-width);
  box-shadow: var(--balsa-shadow-control);
}

:where([data-balsa="button"])[data-variant="glass"]:not(:disabled) {
  border-color: color-mix(in oklab, var(--balsa-material-glass-control-border) var(--balsa-border-opacity, 100%), transparent);
  background-color: var(--balsa-material-glass-control);
}

:where([data-balsa="button"])[data-variant="glass"]:hover:not(:disabled) {
  background-color: var(--balsa-material-glass-control-hover);
}

:where([data-balsa="button"])[data-variant="glass"]:active:not(:disabled) {
  background-color: var(--balsa-material-glass-control-active);
}

/* Theme-owned outline materials keep lower-emphasis actions transparent in
   flat themes while retaining a semantic, deliberately visible boundary. */
:where(
  [data-balsa="button"],
  [data-balsa="link"]
)[data-variant="outline"]:not(:disabled) {
  border-color: color-mix(in oklab, var(--balsa-material-outline-control-border) var(--balsa-border-opacity, 100%), transparent);
  background-color: var(--balsa-material-outline-control);
}

:where(
  [data-balsa="button"],
  [data-balsa="link"]
)[data-variant="outline"]:hover:not(:disabled) {
  background-color: var(--balsa-material-outline-control-hover);
}

:where(
  [data-balsa="button"],
  [data-balsa="link"]
)[data-variant="outline"]:active:not(:disabled) {
  background-color: var(--balsa-material-outline-control-active);
}

:where([data-balsa="button"], [data-balsa="link"]):hover:not(:disabled) {
  transform: var(--balsa-control-hover-transform);
}

:where([data-balsa="button"], [data-balsa="link"]):active:not(:disabled) {
  transform: var(--balsa-control-active-transform);
}

/* Connected buttons move and elevate as one control so their effects do not
   expand the group's intentionally scrollable inline axis. */
[data-balsa="button-group"] > [data-balsa="button"] {
  box-shadow: none;
  transform: none;
}

[data-balsa="button-group"] > [data-balsa="button"]:hover:not(:disabled),
[data-balsa="button-group"] > [data-balsa="button"]:active:not(:disabled) {
  transform: none;
}

:where([data-balsa="button"], [data-balsa="link"])[data-variant="text"] {
  border-width: 0;
  box-shadow: none;
  transform: none;
}

[data-balsa="badge"] {
  border-radius: var(--balsa-radius-badge);
  border-style: var(--balsa-border-style);
  font-family: var(--balsa-control-font-family);
  font-weight: var(--balsa-control-font-weight);
  letter-spacing: var(--balsa-control-letter-spacing);
  text-transform: var(--balsa-control-text-transform);
}

[data-balsa="badge"][data-variant="outline"] {
  border-width: var(--balsa-outline-border-width);
}

[data-balsa="card"] {
  border-radius: var(--balsa-radius-surface);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  transition-property: transform, box-shadow, background-color, border-color;
  transition-duration: var(--balsa-motion-normal);
}

[data-balsa="card"][data-variant="outline"] {
  border-width: var(--balsa-outline-border-width);
}

[data-application-card-footer] {
  border-top-width: var(--balsa-border-width);
  border-top-style: var(--balsa-border-style);
}

[data-balsa="card"][data-variant="surface"] {
  box-shadow: var(--balsa-shadow-surface);
}

[data-balsa="card"][data-variant="elevated"] {
  box-shadow: var(--balsa-shadow-panel);
}

[data-balsa="card"][data-balsa-playground] {
  box-shadow: var(--balsa-shadow-playground);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

[data-balsa="table"][data-density="compact"] {
  --balsa-table-density: var(--balsa-spacing-density-compact);
}

[data-balsa="table"][data-density="default"] {
  --balsa-table-density: var(--balsa-spacing-density-default);
}

[data-balsa="table"][data-density="comfortable"] {
  --balsa-table-density: var(--balsa-spacing-density-comfortable);
}

[data-balsa="table"] :where(th, td) {
  padding-block: var(--balsa-table-density);
  padding-inline: calc(var(--balsa-table-density) + 0.25rem);
}

/* ---------------------------------------------------------------------------
   Concentric nesting.

   A surface publishes, for whatever it contains, two things it is the only one
   in a position to know: the shadow a contained surface should wear instead of
   repeating this one, and the radius that keeps the gap between the two edges
   even.

   Inheritance does the nesting detection. A contained surface reads the
   variable and gets the quieter treatment; the same surface standing on its own
   finds nothing published, falls back, and elevates in full. No selector has to
   ask how deep it is.

   Concentric radius follows the rule that an inner corner is the outer corner
   minus the padding between them. Equal radii read as a gap that thickens at
   every corner, which is the flaw the rule exists to fix. Clamped at zero
   because a padding larger than the radius means a square inner corner, not a
   negative one.

   The published radius reaches every descendant, not only a direct child, so a
   surface nested two deep is inset further than the arithmetic assumes. That is
   deliberate: the alternative is threading the value through every level, and a
   second-level surface is rare enough that being slightly generous beats being
   wrong everywhere.
   --------------------------------------------------------------------------- */

[data-balsa="card"][data-padding="none"] { --balsa-surface-padding: 0px; }
[data-balsa="card"][data-padding="sm"] { --balsa-surface-padding: 1rem; }
[data-balsa="card"][data-padding="md"] { --balsa-surface-padding: 1.25rem; }
[data-balsa="card"][data-padding="lg"] { --balsa-surface-padding: 1.5rem; }

/* ApplicationCard hands Card `padding="none"` and pads its own regions, so the
   inset its body actually uses has to be declared here rather than inferred. */
[data-balsa="card"][data-application-card] { --balsa-surface-padding: 1.25rem; }
[data-balsa="card"][data-application-card][data-size="sm"] { --balsa-surface-padding: 1rem; }
[data-balsa="card"][data-application-card][data-size="lg"] { --balsa-surface-padding: 1.5rem; }

:where(
  [data-balsa="card"],
  [data-balsa="modal-panel"],
  [data-balsa="drawer-panel"],
  [data-balsa="popup-panel"],
  [data-balsa="menu-list"]
) {
  --balsa-shadow-contained: var(--balsa-shadow-detail);
  /* Floored at one base unit, and never above the radius it nests inside.
     The pure subtraction is right and degenerates here: Balsa pads further
     than it curves -- 16px of inset against a 14px surface radius -- so it
     clamps to zero and squares off every contained corner. That proportion is
     not an accident and is shared with shadcn, whose card is a 12px radius with
     24px of padding, so correcting it by growing the radius would pull away
     from the ecosystem Balsa is built on.
     The floor is the documented answer for this case: where the subtraction
     reaches zero, a small inner radius is chosen by eye, typically a few
     pixels. One base unit is that value, expressed as a token rather than as a
     number nobody can trace.
     The upper clamp keeps a square design system square: Brutalism curves by
     0px, and a floor with no ceiling would round its inner corners while its
     outer corners stayed sharp. */
  --balsa-radius-contained: min(
    var(--balsa-radius-surface),
    max(
      var(--balsa-space-unit),
      calc(var(--balsa-radius-surface) - var(--balsa-surface-padding, 0px))
    )
  );
}

/* A bordered surface elevates on its own and stays quiet inside another. Before
   this, none of them elevated at all: `data-shadow` only ever had rules for the
   explicit none/sm/md/lg, and every component defaults to `auto`, which had no
   rule anywhere. */
:where(
  [data-balsa="alert"],
  [data-balsa="table"],
  [data-balsa="scroll-area"],
  [data-balsa="resizable"]
)[data-shadow="auto"] {
  box-shadow: var(--balsa-shadow-contained, var(--balsa-shadow-surface));
}

/* The concentric corner, for a surface that asked for one. `auto` emits no
   radius utility, so this is the only declaration and nothing outranks it. A
   surface with nothing published above it falls back to the ordinary surface
   radius and reads exactly as it did before. */
:where(
  [data-balsa="alert"],
  [data-balsa="table"],
  [data-balsa="scroll-area"],
  [data-balsa="resizable"]
)[data-rounded="auto"] {
  border-radius: var(--balsa-radius-contained, var(--balsa-radius-surface));
}

/* `--balsa-radius-contained` is published above and deliberately not consumed
   yet. Every one of these components already sets its own corner from a
   `rounded` prop, compiled to a Tailwind utility, so reading the contained
   radius here would override an explicit choice a caller made through the
   public API rather than filling in a default. Wiring it up needs the prop to
   grow an `auto` that means "concentric with whatever contains me"; until then
   the value is available to anyone who opts in. */

[data-balsa="card"][data-shadow="none"] {
  box-shadow: none;
}

[data-balsa][data-shadow="none"] {
  box-shadow: none;
}

[data-balsa][data-shadow="sm"] {
  box-shadow: var(--balsa-shadow-sm);
}

[data-balsa][data-shadow="md"] {
  box-shadow: var(--balsa-shadow-md);
}

[data-balsa][data-shadow="lg"] {
  box-shadow: var(--balsa-shadow-lg);
}

[data-balsa="button-group"],
[data-balsa="tabs-list"] {
  border-radius: var(--balsa-radius-control);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
}

[data-balsa="tabs-list"][data-type="underline"] {
  border-radius: 0;
  border-width: 0 0 var(--balsa-border-width);
}

[data-balsa="tabs-list"][data-type="pills"],
[data-balsa="tabs-list"][data-type="tiles"] {
  border-radius: 0;
  border-width: 0;
}

[data-balsa="button-group"] {
  box-shadow: var(--balsa-shadow-control);
}

[data-balsa="button-group"][data-variant="code"] {
  border-radius: var(--balsa-code-control-radius);
}

[data-balsa="tabs-panel"][data-surface="true"],
[data-balsa="color-picker-popover"],
[data-balsa="select-popover"],
[data-balsa="autocomplete-popover"] {
  border-radius: var(--balsa-radius-surface);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-surface);
}

[data-balsa="code-block"] {
  border-radius: var(--balsa-radius-control);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  --balsa-code-syntax-comment: color-mix(in oklab, var(--balsa-color-code-foreground) 48%, transparent);
  --balsa-code-syntax-keyword: color-mix(in oklab, var(--balsa-color-info) 64%, var(--balsa-color-code-foreground));
  --balsa-code-syntax-string: color-mix(in oklab, var(--balsa-color-success) 68%, var(--balsa-color-code-foreground));
  --balsa-code-syntax-number: color-mix(in oklab, var(--balsa-color-warning) 72%, var(--balsa-color-code-foreground));
  --balsa-code-syntax-title: color-mix(in oklab, var(--balsa-color-accent) 62%, var(--balsa-color-code-foreground));
  --balsa-code-syntax-variable: color-mix(in oklab, var(--balsa-color-destructive) 58%, var(--balsa-color-code-foreground));
  --balsa-code-syntax-meta: color-mix(in oklab, var(--balsa-color-secondary) 58%, var(--balsa-color-code-foreground));
  --balsa-code-label-color: color-mix(in oklab, var(--balsa-color-code-foreground) 65%, transparent);
}

[data-balsa="code-block"] [data-balsa-code-label] {
  color: var(--balsa-code-label-color);
}

[data-balsa="card"][data-variant="glass"],
[data-balsa="navbar-surface"][data-variant="glass"],
[data-balsa="dropdown"][data-variant="glass"],
[data-balsa="menu-list"][data-variant="glass"],
[data-balsa="site-floating-panel"][data-variant="glass"],
[data-balsa="theme-advanced"][data-variant="glass"],
[data-balsa="theme-advanced"][data-variant="glass"] [data-balsa-theme-advanced-header] {
  background-color: var(--balsa-material-glass-control);
}

[data-balsa="component-playground-workspace"] {
  background-color: var(--balsa-material-playground-workspace);
}

[data-balsa="component-playground-properties"] {
  background-color: var(--balsa-material-playground-properties);
}

[data-balsa="code-block"] :where(.hljs-comment, .hljs-quote) {
  color: var(--balsa-code-syntax-comment);
  font-style: italic;
}

[data-balsa="code-block"] :where(.hljs-keyword, .hljs-selector-tag, .hljs-attribute, .hljs-name) {
  color: var(--balsa-code-syntax-keyword);
}

[data-balsa="code-block"] :where(.hljs-string, .hljs-doctag, .hljs-regexp, .hljs-addition) {
  color: var(--balsa-code-syntax-string);
}

[data-balsa="code-block"] :where(.hljs-number, .hljs-literal, .hljs-symbol, .hljs-bullet) {
  color: var(--balsa-code-syntax-number);
}

[data-balsa="code-block"] :where(.hljs-title, .hljs-section, .hljs-selector-id, .hljs-selector-class, .hljs-tag) {
  color: var(--balsa-code-syntax-title);
}

[data-balsa="code-block"] :where(.hljs-variable, .hljs-template-variable, .hljs-deletion) {
  color: var(--balsa-code-syntax-variable);
}

[data-balsa="code-block"] :where(.hljs-meta, .hljs-built_in, .hljs-type) {
  color: var(--balsa-code-syntax-meta);
}

[data-balsa="code-block"] :where(.hljs-strong, .hljs-title, .hljs-section) {
  font-weight: 700;
}

[data-balsa="code-block"] {
  --balsa-code-label-color: color-mix(in oklab, var(--balsa-color-code-foreground) 82%, transparent);
  --balsa-code-syntax-comment: color-mix(in oklab, var(--balsa-color-code-foreground) 64%, transparent);
}

[data-balsa="code-block"] :where(
  [data-balsa="button"],
  [data-balsa="link"]
)[data-variant="outline"] {
  --balsa-material-outline-control: color-mix(in oklab, var(--balsa-color-code-foreground) 8%, transparent);
  --balsa-material-outline-control-hover: color-mix(in oklab, var(--balsa-color-code-foreground) 14%, transparent);
  --balsa-material-outline-control-active: color-mix(in oklab, var(--balsa-color-code-foreground) 20%, transparent);
  --balsa-material-outline-control-border: color-mix(in oklab, var(--balsa-color-code-foreground) 28%, transparent);
}

[data-balsa="modal-panel"] {
  border-radius: var(--balsa-radius-panel);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-panel);
}

[data-balsa="dropdown"] {
  border-radius: var(--balsa-radius-surface);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
}

[data-balsa="navbar-surface"],
[data-balsa="dropdown"],
[data-balsa="color-picker-popover"],
[data-balsa="select-popover"],
[data-balsa="autocomplete-popover"],
:where([data-balsa="button"])[data-variant="glass"] {
  backdrop-filter: var(--balsa-backdrop-filter);
  -webkit-backdrop-filter: var(--balsa-backdrop-filter);
}

[data-balsa="modal-panel"][data-variant="glass"]:not([data-presentation="fullscreen"]) {
  backdrop-filter: var(--balsa-backdrop-filter);
  -webkit-backdrop-filter: var(--balsa-backdrop-filter);
}

[data-balsa="modal-backdrop"] {
  backdrop-filter: var(--balsa-overlay-filter);
  -webkit-backdrop-filter: var(--balsa-overlay-filter);
}

[data-balsa="checkbox-control"] {
  border-radius: min(var(--balsa-radius-control), 0.25rem);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
}

/* An avatar and a one-time-code cell both draw an edge and had no rule to draw
   it from, so each carried a bare `border` -- a literal 1px that no border
   setting could reach. */
[data-balsa="avatar"],
[data-balsa="input-otp-cell"],
[data-balsa="radio-group-indicator"],
[data-balsa="table"],
[data-balsa="calendar"],
[data-balsa="scroll-area"],
[data-balsa="resizable"],
[data-balsa="carousel-viewport"],
[data-balsa="alert"] {
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
}

[data-balsa="switch-control"] {
  border-radius: var(--balsa-radius-toggle);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-control);
}

[data-balsa="switch-control"]::after {
  border-radius: var(--balsa-radius-toggle);
}

[data-balsa="toggle"] {
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-control);
  font-family: var(--balsa-control-font-family);
  font-weight: var(--balsa-control-font-weight);
  letter-spacing: var(--balsa-control-letter-spacing);
  text-transform: var(--balsa-control-text-transform);
}

[data-balsa="toggle"][data-variant="solid"] {
  border-width: var(--balsa-solid-border-width);
}

[data-balsa="toggle"][data-variant="surface"],
[data-balsa="toggle"][data-variant="outline"],
[data-balsa="toggle"][data-variant="glass"] {
  border-width: var(--balsa-outline-border-width);
}

[data-balsa="toggle"][data-variant="glass"][data-state="off"] {
  backdrop-filter: var(--balsa-backdrop-filter-contained);
  -webkit-backdrop-filter: var(--balsa-backdrop-filter-contained);
}

[data-balsa="toggle"]:hover:not(:disabled) {
  transform: var(--balsa-control-hover-transform);
}

[data-balsa="toggle"]:active:not(:disabled) {
  transform: var(--balsa-control-active-transform);
}

[data-balsa="toggle-group"] {
  border-radius: var(--balsa-radius-control);
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-control);
}

[data-balsa="toggle-group"] > [data-balsa="toggle"],
[data-balsa="toggle-group"] > [data-balsa="toggle"]:hover:not(:disabled),
[data-balsa="toggle-group"] > [data-balsa="toggle"]:active:not(:disabled) {
  box-shadow: none;
  transform: none;
}

[data-balsa="collapsible"]:not([data-variant="underline"]),
[data-balsa="accordion"]:not([data-variant="underline"]) {
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  box-shadow: var(--balsa-shadow-control);
}

[data-balsa="collapsible-trigger"] {
  font-family: var(--balsa-control-font-family);
  font-weight: var(--balsa-control-font-weight);
  letter-spacing: var(--balsa-control-letter-spacing);
}

[data-balsa="accordion"] > [data-balsa="collapsible"] {
  border-width: 0;
  box-shadow: none;
}

[data-balsa="accordion"] > [data-balsa="collapsible"]:not(:first-child) {
  border-top-width: var(--balsa-border-width);
}

/* A key cap is monospace by convention, so the component sets `font-mono` and
   the typography control deliberately does not move it. This rule used to
   declare `font-family: var(--balsa-control-font-family)` as well, which never
   applied -- the utility won every time -- and read as though the body face
   were meant to reach here. */
[data-balsa="kbd"][data-group="false"],
[data-balsa="kbd-key"] {
  border-width: var(--balsa-border-width);
  border-style: var(--balsa-border-style);
  letter-spacing: var(--balsa-control-letter-spacing);
}

[data-balsa="kbd"][data-variant="raised"][data-shadow="auto"][data-group="false"],
[data-balsa="kbd"][data-variant="raised"][data-shadow="auto"] [data-balsa="kbd-key"] {
  box-shadow: var(--balsa-shadow-detail);
}

[data-balsa="separator"] {
  font-family: var(--balsa-font-body);
}

@keyframes balsa-skeleton-wave {
  from {
    transform: translateX(-120%);
  }
  to {
    transform: translateX(120%);
  }
}

:where(
  [data-balsa="skeleton"][data-animation="wave"]:not([data-shape="text"]),
  [data-balsa="skeleton-piece"][data-animation="wave"]
)::after {
  position: absolute;
  inset: 0;
  content: "";
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--balsa-color-foreground) 10%, transparent),
    transparent
  );
  transform: translateX(-120%);
  animation: balsa-skeleton-wave 1.5s var(--balsa-motion-easing) infinite;
}

[data-balsa="spinner"],
[data-balsa="progress"],
[data-balsa="alert"],
[data-balsa="toast"],
[data-balsa="toast-viewport"] {
  font-family: var(--balsa-font-body);
}

@keyframes balsa-alert-dialog-enter {
  from {
    opacity: 0;
    transform: translateY(1rem) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

dialog[data-balsa="alert"][open] {
  animation: balsa-alert-dialog-enter 180ms var(--balsa-motion-easing);
}

@keyframes balsa-progress-indeterminate {
  from {
    transform: translateX(-100%);
  }
