function typographyTokens(option: ThemeTypographyOption): NonNullable<ThemeTokens["typography"]> {
  if (option === "mono") {
    const fonts = ["ui-monospace", "SFMono-Regular", "Consolas", "Liberation Mono", "monospace"];
    return {
      titleFonts: fonts,
      bodyFonts: fonts,
      controlFonts: fonts,
      titleLetterSpacing: -0.48,
      titleTextTransform: "uppercase",
      controlWeight: 800,
      controlLetterSpacing: 0.96,
      controlTextTransform: "uppercase",
    };
  }
  const systemFonts = ["ui-sans-serif", "system-ui", "sans-serif"];
  if (option === "system") {
    return {
      titleFonts: systemFonts,
      bodyFonts: systemFonts,
      controlFonts: systemFonts,
      titleLetterSpacing: 0,
      titleTextTransform: "none",
      controlWeight: 600,
      controlLetterSpacing: 0,
      controlTextTransform: "none",
    };
  }
  if (option === "editorial") {
    return {
      titleFonts: ["Georgia", "Cambria", "Times New Roman", "serif"],
      bodyFonts: systemFonts,
      controlFonts: systemFonts,
      titleLetterSpacing: -0.2,
      titleTextTransform: "none",
      controlWeight: 600,
      controlLetterSpacing: 0,
      controlTextTransform: "none",
    };
  }
  return {
    titleFonts: ["Space Grotesk", "sans-serif"],
    bodyFonts: ["Noto Sans", "sans-serif"],
    controlFonts: ["Noto Sans", "sans-serif"],
    titleLetterSpacing: 0,
    titleTextTransform: "none",
    controlWeight: 600,
    controlLetterSpacing: 0,
    controlTextTransform: "none",
  };
}

function radiusTokens(option: ThemeShapeOption): NonNullable<ThemeTokens["radius"]> {
  if (option === "square") {
    return { control: 0, surface: 0, panel: 0, badge: 0, toggle: 0, codeControl: 0 };
  }
  if (option === "subtle") {
    return { control: 4, surface: 8, panel: 12, badge: 4, toggle: 4, codeControl: 4 };
  }
  if (option === "soft") {
    return { control: 12, surface: 18, panel: 24, badge: 9999, toggle: 9999, codeControl: 8 };
  }
  return { control: 8, surface: 14, panel: 18, badge: 9999, toggle: 9999, codeControl: 8 };
}

/**
 * The spacing scale's base unit, and the legacy density values.
 *
 * Only the unit moves. Every rhythm step and every control inset is a multiple
 * of it, so scaling the unit scales the whole system in proportion and the
 * ratios between steps survive -- which is the property that makes a scale a
 * scale rather than a list of sizes.
 *
 * Half-pixel steps are deliberate. A 4px unit puts the heaviest-used step on
 * 12px; 3.5 and 4.5 move that to 10.5 and 13.5, which is a perceptible change
 * in rhythm without breaking the ladder into values nobody chose.
 */
function spacingTokens(
  option: ThemeSpacingOption,
  size: ThemeSizeOption,
): NonNullable<ThemeTokens["spacing"]> {
  const unit = option === "tight" ? 3.5 : option === "airy" ? 4.5 : 4;
  // `controlInline` predates the split and now describes the size dimension,
  // not the spacing one. The composition matrix still reads it to size a tile
  // against the control scale.
  const controlInline = size === "compact" ? 12 : size === "comfortable" ? 20 : 16;
  return { unit, controlInline, densityCompact: 4, densityDefault: 8, densityComfortable: 12 };
}

function borderTokens(option: ThemeBorderOption): NonNullable<ThemeTokens["border"]> {
  if (option === "none") {
    return { width: 0, outlineWidth: 0, solidWidth: 0, opacity: 1, style: "solid" };
  }
  if (option === "soft") {
    return { width: 1, outlineWidth: 1, solidWidth: 1, opacity: 0.55, style: "solid" };
  }
  if (option === "strong") {
    return { width: 2, outlineWidth: 2, solidWidth: 2, opacity: 1, style: "solid" };
  }
  return { width: 1, outlineWidth: 1, solidWidth: 1, opacity: 1, style: "solid" };
}

function shadowLayer(
  x: number,
  y: number,
  blur: number,
  opacity = 1,
  spread = 0,
): ThemeShadowLayer {
  return { x, y, blur, spread, color: { role: "foreground", opacity } };
}

function shadowTokens(option: ThemeElevationOption): NonNullable<ThemeTokens["shadow"]> {
  if (option === "none") return { sm: [], md: [], lg: [], detail: [] };
  if (option === "hard") {
    return {
      sm: [shadowLayer(3, 3, 0)],
      md: [shadowLayer(5, 5, 0)],
      lg: [shadowLayer(6, 6, 0)],
      detail: [shadowLayer(2, 2, 0)],
    };
  }
  if (option === "floating") {
    return {
      sm: [shadowLayer(0, 6, 20, 0.04)],
      md: [shadowLayer(0, 14, 36, 0.05)],
      lg: [shadowLayer(0, 8, 24, 0.05)],
      detail: [shadowLayer(0, 1, 2, 0.08)],
    };
  }
  return {
    sm: [],
    md: [shadowLayer(0, 1, 2, 0.08), shadowLayer(0, 12, 32, 0.08)],
    lg: [shadowLayer(0, 1, 2, 0.06), shadowLayer(0, 12, 32, 0.07)],
    detail: [shadowLayer(0, 1, 2, 0.1)],
  };
}

function motionTokens(option: ThemeMotionOption): NonNullable<ThemeTokens["motion"]> {
  if (option === "none") {
    return {
      fast: 0,
      normal: 0,
      slow: 0,
      easing: "linear",
      controlHover: {},
      controlActive: {},
      surfaceHover: {},
    };
  }
  if (option === "snappy") {
    return {
      fast: 90,
      normal: 140,
      slow: 220,
      easing: "linear",
      controlHover: { x: -2, y: -2 },
      controlActive: { x: 1, y: 1 },
      surfaceHover: { x: -2, y: -2 },
    };
  }
  if (option === "fluid") {
    return {
      fast: 180,
      normal: 320,
      slow: 520,
      easing: [0.22, 1, 0.36, 1],
      controlHover: { y: -1, scale: 1.01 },
      controlActive: { scale: 0.98 },
      surfaceHover: {},
    };
  }
  return {
    fast: 160,
    normal: 260,
    slow: 420,
    easing: [0.2, 0.8, 0.2, 1],
    controlHover: { y: -1 },
    controlActive: { y: 0 },
    surfaceHover: {},
  };
}

function shapeDefaults(option: ThemeShapeOption): ThemeDefaults {
  if (option === "rounded" || option === "soft") return {};
  const roundedByShape: Record<"square" | "subtle", Record<ThemeFamily, Rounded>> = {
    square: { controls: "none", fields: "none", surfaces: "none", overlays: "none", navigation: "none" },
    subtle: { controls: "sm", fields: "sm", surfaces: "lg", overlays: "lg", navigation: "sm" },
  };
  return {
    families: Object.fromEntries(
      Object.entries(roundedByShape[option]).map(([family, rounded]) => [
        family,
        { rounded },
      ]),
    ),
  };
}

/**
 * The size dimension, applied as each component's default size.
 *
 * `Table` and `DataTable` are the exception: their row height is their own
 * `density` prop, so the theme's size maps onto it by name rather than through
 * `size`. That is why this dimension could not simply be renamed everywhere —
 * two different things were spelled the same, and only one of them moved.
 */
function sizeDefaults(option: ThemeSizeOption): ThemeDefaults {
  const density = option === "compact" ? "compact" : option === "comfortable" ? "comfortable" : "default";
  const components: Partial<ThemeComponentDefaultMap> = {};
  for (const component of themeDefaultPropCoverage.size) {
    if (component === "scroll-area") {
      components[component] = { size: option === "compact" ? "thin" : "regular" };
    } else {
      const supportedSizes = themeComponentSizeOptions[component];
      const size = option === "compact"
        ? "sm"
        : option === "comfortable" && supportedSizes?.includes("lg")
          ? "lg"
          : "md";
      components[component] = { size } as never;
    }
  }
  components.table = { ...(components.table ?? {}), density };
  components["data-table"] = { ...(components["data-table"] ?? {}), density };
  return { components };
}

function elevationDefaults(option: ThemeElevationOption): ThemeDefaults {
  if (option !== "none") return {};
  return {
    families: {
      controls: { shadow: "none" },
      fields: { shadow: "none" },
      surfaces: { shadow: "none" },
      overlays: { shadow: "none" },
      navigation: { shadow: "none" },
    },
  };
}

function materialDefaults(option: ThemeMaterialOption): ThemeDefaults {
  if (option !== "glass") return {};
  return {
    components: {
      // Card carries the recipe's translucent surface material either way, so
      // without its typed glass variant it renders a see-through fill with no
      // backdrop to filter — the panel reads as broken rather than frosted.
      card: { variant: "glass" },
      "button-group": { variant: "glass" },
      popup: { variant: "glass" },
      "hover-card": { variant: "glass" },
      tooltip: { variant: "glass" },
      "dropdown-menu": { variant: "glass" },
      "context-menu": { variant: "glass" },
      menubar: { variant: "glass" },
      "command-menu": { variant: "glass" },
      drawer: { variant: "glass" },
      "color-picker": { variant: "glass" },
      modal: { variant: "glass" },
      select: { variant: "glass" },
      autocomplete: { variant: "glass" },
      dropdown: { variant: "glass" },
      navbar: { variant: "glass", type: "floating" },
    },
  };
}

export interface DerivedThemeRecipe {
  tokens: ThemeTokens;
  defaults: ThemeDefaults;
}

export function deriveThemeRecipe(options: ResolvedThemeOptions): DerivedThemeRecipe {
  const material = materialTokens(options.material);
  return {
    tokens: {
      typography: typographyTokens(options.typography),
      radius: radiusTokens(options.shape),
      spacing: spacingTokens(options.spacing, options.size),
      border: borderTokens(options.border),
      shadow: shadowTokens(options.elevation),
      motion: motionTokens(options.motion),
      effects: material.effects,
      materials: material.materials,
    },
    defaults: mergeThemeDefaults(
      mergeThemeDefaults(shapeDefaults(options.shape), sizeDefaults(options.size)),
      mergeThemeDefaults(elevationDefaults(options.elevation), materialDefaults(options.material)),
    ),
  };
}

function mergeThemeTokens(parent: ThemeTokens, child: ThemeTokens): ThemeTokens {
  return {
    typography: { ...parent.typography, ...child.typography },
    radius: { ...parent.radius, ...child.radius },
    spacing: { ...parent.spacing, ...child.spacing },
    border: { ...parent.border, ...child.border },
    shadow: { ...parent.shadow, ...child.shadow },
    motion: { ...parent.motion, ...child.motion },
    effects: { ...parent.effects, ...child.effects },
    materials: { ...parent.materials, ...child.materials },
  };
}

function mergeThemeDefaults(parent: ThemeDefaults, child: ThemeDefaults): ThemeDefaults {
  const familyKeys: readonly ThemeFamily[] = [
    "controls",
    "fields",
    "surfaces",
    "overlays",
    "navigation",
  ];
  const componentKeys = new Set<ThemeComponentName>([
    ...Object.keys(parent.components ?? {}) as ThemeComponentName[],
    ...Object.keys(child.components ?? {}) as ThemeComponentName[],
  ]);

  return {
    families: Object.fromEntries(
      familyKeys.map((family) => [
        family,
        {
          ...parent.families?.[family],
          ...child.families?.[family],
        },
      ]),
    ),
    components: Object.fromEntries(
      [...componentKeys].map((component) => [
        component,
        {
          ...parent.components?.[component],
          ...child.components?.[component],
        },
      ]),
    ),
  };
}

interface ThemeResolutionState {
  id: string;
  name: string;
  base: DesignTheme;
  options: ResolvedThemeOptions;
  tokenOverrides: ThemeTokens;
  defaultOverrides: ThemeDefaults;
}

function resolveThemeState(input: ThemeInput): ThemeResolutionState {
  if (isDesignTheme(input)) {
    const metadata = designThemes.find(({ id }) => id === input);
    return {
      id: input,
      name: metadata?.label ?? input,
      base: input,
      options: { ...builtInThemeOptions[input] },
      tokenOverrides: {},
      defaultOverrides: {},
    };
  }

  validateThemeDefinition(input, new Set());
  const parent = resolveThemeState(input.extends);
  return {
    id: input.id,
    name: input.name.trim(),
    base: parent.base,
    options: { ...parent.options, ...input.options },
    tokenOverrides: mergeThemeTokens(
      parent.tokenOverrides,
      mergeThemeTokens(input.tokens ?? {}, input.overrides?.tokens ?? {}),
    ),
    defaultOverrides: mergeThemeDefaults(
      parent.defaultOverrides,
      mergeThemeDefaults(input.defaults ?? {}, input.overrides?.defaults ?? {}),
    ),
  };
}

export function resolveTheme(input: ThemeInput): ResolvedThemeDefinition {
  const state = resolveThemeState(input);
  const derived = deriveThemeRecipe(state.options);
  return {
    id: state.id,
    name: state.name,
    base: state.base,
    options: state.options,
    tokens: mergeThemeTokens(derived.tokens, state.tokenOverrides),
    defaults: mergeThemeDefaults(derived.defaults, state.defaultOverrides),
  };
}

/**
 * A material refers to the *resolved* role, not the raw palette anchor.
 *
 * A palette defines the anchors and leaves the derived roles to the foundation,
 * so `var(--balsa-color-accent-hover)` had nothing to resolve — and a `var()`
 * on an undefined custom property with no fallback is invalid at computed-value
 * time, which makes the whole material variable vanish rather than fall back.
 * The failure was silent and only visible as a surface that stopped being glass
 * on hover. `--balsa-role-*` always resolves, so a material always has a value.
 */
function paletteColorReference(role: ThemeColorReference["role"]): string {
  if (role === "currentColor" || role === "transparent") return role;
  return `var(--balsa-role-${role})`;
}

function percentage(value: number): string {
  return `${Math.round(value * 10_000) / 100}%`;
}

function serializeColorReference(reference: ThemeColorReference): string {
  const color = paletteColorReference(reference.role);
  const opacity = reference.opacity ?? 1;
  if (reference.role === "transparent" || opacity === 1) return color;
  return `color-mix(in oklab, ${color} ${percentage(opacity)}, transparent)`;
}

function serializeMaterial(material: ThemeMaterial): string {
  if (!material.tint) return serializeColorReference(material);
  const source = paletteColorReference(material.role);
  const tint = paletteColorReference(material.tint.role);
  return `color-mix(in oklab, ${source} ${percentage(material.opacity ?? 1)}, ${tint} ${percentage(material.tint.opacity ?? 1)})`;
}

function serializeShadow(layers: readonly ThemeShadowLayer[]): string {
  if (!layers.length) return "none";
  return layers.map((layer) => [
    layer.inset ? "inset" : "",
    `${layer.x}px`,
    `${layer.y}px`,
    `${layer.blur}px`,
    `${layer.spread ?? 0}px`,
    serializeColorReference(layer.color),
  ].filter(Boolean).join(" ")).join(", ");
}

function serializeTransform(transform: ThemeTransform): string {
  const values = [];
  if (transform.x !== undefined || transform.y !== undefined) {
    values.push(`translate(${transform.x ?? 0}px, ${transform.y ?? 0}px)`);
  }
  if (transform.scale !== undefined) values.push(`scale(${transform.scale})`);
  return values.join(" ") || "none";
}

function serializeEasing(easing: ThemeEasing): string {
  return typeof easing === "string"
    ? easing
    : `cubic-bezier(${easing.join(", ")})`;
}

function serializeFontStack(fonts: readonly string[]): string {
  return fonts.map((font) =>
    /\s/.test(font) && !/^["'].*["']$/.test(font) ? JSON.stringify(font) : font
  ).join(", ");
}

export function serializeThemeTokens(tokens: ThemeTokens): Readonly<Record<string, string>> {
  const declarations: Record<string, string> = {};
  const assign = (name: string, value: string | undefined): void => {
    if (value !== undefined) declarations[name] = value;
  };

  assign("--balsa-font-title", tokens.typography?.titleFonts
    ? serializeFontStack(tokens.typography.titleFonts)
    : undefined);
  assign("--balsa-font-body", tokens.typography?.bodyFonts
    ? serializeFontStack(tokens.typography.bodyFonts)
    : undefined);
  assign("--balsa-control-font-family", tokens.typography?.controlFonts
    ? serializeFontStack(tokens.typography.controlFonts)
    : undefined);
  assign("--balsa-title-letter-spacing", tokens.typography?.titleLetterSpacing === undefined
    ? undefined
    : `${tokens.typography.titleLetterSpacing}px`);
  assign("--balsa-title-text-transform", tokens.typography?.titleTextTransform);
  assign("--balsa-control-font-weight", tokens.typography?.controlWeight?.toString());
  assign("--balsa-control-letter-spacing", tokens.typography?.controlLetterSpacing === undefined
    ? undefined
    : `${tokens.typography.controlLetterSpacing}px`);
  assign("--balsa-control-text-transform", tokens.typography?.controlTextTransform);

  const radiusVariables = {
    control: "--balsa-radius-control",
    surface: "--balsa-radius-surface",
    panel: "--balsa-radius-panel",
    badge: "--balsa-radius-badge",
    toggle: "--balsa-radius-toggle",
    codeControl: "--balsa-code-control-radius",
  } as const;
  for (const [key, variable] of Object.entries(radiusVariables)) {
    const value = tokens.radius?.[key as keyof NonNullable<ThemeTokens["radius"]>];
    assign(variable, value === undefined ? undefined : `${value}px`);
  }
  const spacingVariables = {
    unit: "--balsa-space-unit",
    controlInline: "--balsa-spacing-control-inline",
    densityCompact: "--balsa-spacing-density-compact",
    densityDefault: "--balsa-spacing-density-default",
    densityComfortable: "--balsa-spacing-density-comfortable",
  } as const;
  for (const [key, variable] of Object.entries(spacingVariables)) {
    const value = tokens.spacing?.[key as keyof NonNullable<ThemeTokens["spacing"]>];
    assign(variable, value === undefined ? undefined : `${value}px`);
  }

  const borderVariables = {
    width: "--balsa-border-width",
    outlineWidth: "--balsa-outline-border-width",
    solidWidth: "--balsa-solid-border-width",
  } as const;
  for (const [key, variable] of Object.entries(borderVariables)) {
    const value = tokens.border?.[key as keyof typeof borderVariables];
    assign(variable, value === undefined ? undefined : `${value}px`);
  }
  assign(
    "--balsa-border-opacity",
    tokens.border?.opacity === undefined ? undefined : percentage(tokens.border.opacity),
  );
  assign("--balsa-border-style", tokens.border?.style);

  for (const level of ["sm", "md", "lg", "detail"] as const) {
    const value = tokens.shadow?.[level];
    assign(`--balsa-shadow-${level}`, value ? serializeShadow(value) : undefined);
  }

  for (const speed of ["fast", "normal", "slow"] as const) {
    const value = tokens.motion?.[speed];
    assign(`--balsa-motion-${speed}`, value === undefined ? undefined : `${value}ms`);
  }
  assign("--balsa-motion-easing", tokens.motion?.easing
    ? serializeEasing(tokens.motion.easing)
    : undefined);
  assign("--balsa-control-hover-transform", tokens.motion?.controlHover
    ? serializeTransform(tokens.motion.controlHover)
    : undefined);
  assign("--balsa-control-active-transform", tokens.motion?.controlActive
    ? serializeTransform(tokens.motion.controlActive)
    : undefined);
  assign("--balsa-surface-hover-transform", tokens.motion?.surfaceHover
    ? serializeTransform(tokens.motion.surfaceHover)
    : undefined);

  assign("--balsa-backdrop-blur", tokens.effects?.backdropBlur === undefined
    ? undefined
    : `${tokens.effects.backdropBlur}px`);
  assign("--balsa-backdrop-saturation", tokens.effects?.backdropSaturation?.toString());
  assign("--balsa-overlay-blur", tokens.effects?.overlayBlur === undefined
    ? undefined
    : `${tokens.effects.overlayBlur}px`);

  /*
   * The composed filters, resolved to `none` when they would do nothing.
   *
   * `backdrop-filter: blur(0px) saturate(1)` looks identical to `none` and is
   * not the same declaration: any computed value other than `none` creates a
   * stacking context, a containing block for absolute and fixed descendants,
   * and a compositing layer the browser repaints on every scroll frame. A
   * `position: fixed` child of such an element is fixed to the element rather
   * than to the viewport, which is a correctness bug rather than a slow one.
   *
   * Measured on the gallery before this existed: 32 elements carried an
   * identity filter at the Solid material and 24 carried a real blur over a
   * fully opaque background at Glass, where nothing shows through to filter.
   *
   * CSS cannot make this decision -- it has no conditional, and the blur is a
   * runtime value an authored theme sets -- so it is made here, where the
   * number is known, and mirrored by static defaults in `balsa-theme.css` for
   * the path where no theme has been applied yet.
   */
  const blur = tokens.effects?.backdropBlur;
  const saturation = tokens.effects?.backdropSaturation ?? 1;
  const filterFor = (radius: number) =>
    radius > 0 ? `blur(${radius}px) saturate(${saturation})` : "none";
  if (blur !== undefined) {
    assign("--balsa-backdrop-filter", filterFor(blur));
    // A glass surface inside another blurs less: the layer beneath it is
    // already frosted, so repeating the full radius reads as muddy rather than
    // deeper. Floored at zero, and `none` once it gets there.
    assign("--balsa-backdrop-filter-contained", filterFor(Math.max(0, blur - 4)));
  }
  const overlayBlur = tokens.effects?.overlayBlur;
  if (overlayBlur !== undefined) {
    assign("--balsa-overlay-filter", overlayBlur > 0 ? `blur(${overlayBlur}px)` : "none");
  }

  for (const [key, material] of Object.entries(tokens.materials ?? {})) {
    if (material) assign(`--balsa-material-${key}`, serializeMaterial(material));
  }

  return declarations;
}

export function themePresentation(input: ThemeInput): ThemePresentation {
  if (isDesignTheme(input)) return { id: input, style: {} };
  const resolved = resolveTheme(input);
  return {
    id: resolved.id,
    base: resolved.base,
    style: serializeThemeTokens(resolved.tokens),
  };
}

function compactThemeStructure(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(compactThemeStructure);
  if (!value || typeof value !== "object") return value;
  const entries = Object.entries(value as Record<string, unknown>)
    .map(([key, entry]) => [key, compactThemeStructure(entry)] as const)
    .filter(([, entry]) => {
      if (entry === undefined) return false;
      if (Array.isArray(entry)) return true;
      return !entry || typeof entry !== "object" || Object.keys(entry).length > 0;
    });
  return Object.fromEntries(entries);
}

export function normalizeThemeDefinition(definition: ThemeDefinition): ThemeDefinition {
  defineTheme(definition);
  const tokenOverrides = compactThemeStructure(mergeThemeTokens(
    definition.tokens ?? {},
    definition.overrides?.tokens ?? {},
  )) as ThemeTokens;
  const defaultOverrides = compactThemeStructure(mergeThemeDefaults(
    definition.defaults ?? {},
    definition.overrides?.defaults ?? {},
  )) as ThemeDefaults;
  const hasTokenOverrides = Object.keys(tokenOverrides).length > 0;
  const hasDefaultOverrides = Object.keys(defaultOverrides).length > 0;
  return {
    id: definition.id,
    name: definition.name.trim(),
    extends: isDesignTheme(definition.extends)
      ? definition.extends
      : normalizeThemeDefinition(definition.extends),
    ...(definition.options && Object.keys(definition.options).length
      ? { options: { ...definition.options } }
      : {}),
    ...(hasTokenOverrides || hasDefaultOverrides
      ? {
          overrides: {
            ...(hasTokenOverrides ? { tokens: tokenOverrides } : {}),
            ...(hasDefaultOverrides ? { defaults: defaultOverrides } : {}),
          },
        }
      : {}),
  };
}

function normalizePresetThemeOptions(value: unknown): ThemeOptions | undefined {
  if (value === undefined) return undefined;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return value as ThemeOptions;
  }
  const options = value as Record<string, unknown>;
  const border = options.border === "subtle" ? "medium" : options.border;
  return {
    ...options,
    ...(border === undefined ? {} : { border }),
  } as ThemeOptions;
}

export function normalizeThemePresetConfig(value: unknown): BalsaThemePresetConfig {
  if (!value || typeof value !== "object") {
    throw new TypeError("Theme preset configuration must be an object.");
  }
  const candidate = value as Partial<BalsaThemePresetConfig>;
  if (candidate.schemaVersion !== 1) {
    throw new TypeError(
      `Unsupported Balsa theme preset schema version: ${String(candidate.schemaVersion)}.`,
    );
  }
  if (!isDesignTheme(candidate.base)) {
    throw new TypeError("Theme preset base must be a built-in Balsa theme.");
  }
  const normalized = normalizeThemeDefinition({
    id: "balsa-preset-config",
    name: "Balsa preset config",
    extends: candidate.base,
    options: normalizePresetThemeOptions(candidate.options),
    overrides: candidate.overrides,
  });
  return {
    schemaVersion: 1,
    base: candidate.base,
    ...(normalized.options ? { options: normalized.options } : {}),
    ...(normalized.overrides?.tokens
      ? { overrides: { tokens: normalized.overrides.tokens } }
      : {}),
  };
}

export function serializeThemeDefinition(
  definition: ThemeDefinition,
  exportName = "customTheme",
): string {
  defineTheme(definition);
  const identifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(exportName)
    ? exportName
    : "customTheme";
  const normalized = normalizeThemeDefinition(definition);
  return [
    'import { defineTheme } from "@/components/ui/theme";',
    "",
    `export const ${identifier} = defineTheme(${JSON.stringify(normalized, null, 2)});`,
  ].join("\n");
}
import { Blend, Grid3X3, LayoutDashboard } from "@lucide/vue";

export type ThemeRounded =
  | "none"
  | "sm"
  | "md"
  | "lg"
  | "xl"
  | "2xl"
  | "3xl"
  | "full";

export type ThemeShadow = "auto" | "none" | "sm" | "md" | "lg";

type Defaults<
  Variant extends string = never,
  Size extends string | null = never,
  Extra extends object = object,
> = {
  variant?: Variant;
  size?: Size;
} & Extra;

type RoundedDefaults<
  Variant extends string = never,
  Size extends string | null = never,
  Extra extends object = object,
> = Defaults<Variant, Size, Extra> & {
  rounded?: ThemeRounded;
};

type ElevatedDefaults<
  Variant extends string = never,
  Size extends string | null = never,
  Extra extends object = object,
> = Defaults<Variant, Size, Extra> & {
  shadow?: ThemeShadow;
};

type RoundedElevatedDefaults<
  Variant extends string = never,
  Size extends string | null = never,
  Extra extends object = object,
> = RoundedDefaults<Variant, Size, Extra> & {
  shadow?: ThemeShadow;
};

type FieldVariant = "outline" | "surface" | "soft" | "glass";
type FieldSize = "sm" | "md";
type LayerVariant = "surface" | "outline" | "soft" | "glass";
type LayerSize = "sm" | "md" | "lg";
type ActionVariant = "surface" | "solid" | "outline" | "glass";
type SurfaceVariant = "surface" | "outline" | "soft" | "glass";

/**
 * Appearance-only defaults keyed by the public component contract. These
 * unions stay independent from the Vue files so the theme item installs by
 * itself rather than pulling the entire component catalog into a project.
 */
export interface ThemeComponentDefaultMap {
  button: ElevatedDefaults<
    "solid" | "soft" | "outline" | "glass",
    "sm" | "md" | "lg" | "xl" | null,
    { shape?: "rounded" | "pill" | "fab" }
  >;
  "button-group": ElevatedDefaults<
    ActionVariant | "code",
    "sm" | "md" | "lg" | "xl",
    { shape?: "rounded" | "pill" }
  >;
  input: RoundedDefaults<FieldVariant, FieldSize>;
  "input-group": RoundedDefaults<never, FieldSize>;
  "input-otp": RoundedDefaults<FieldVariant | "solid", FieldSize>;
  "radio-group": RoundedDefaults<never, FieldSize>;
  slider: RoundedDefaults<never, LayerSize>;
  popup: RoundedElevatedDefaults<LayerVariant, LayerSize | "trigger">;
  "hover-card": RoundedElevatedDefaults<LayerVariant>;
  tooltip: RoundedElevatedDefaults<LayerVariant>;
  "dropdown-menu": RoundedElevatedDefaults<LayerVariant>;
  "context-menu": RoundedElevatedDefaults<LayerVariant>;
  menubar: RoundedElevatedDefaults<LayerVariant>;
  "command-menu": RoundedElevatedDefaults<LayerVariant, LayerSize>;
  drawer: RoundedElevatedDefaults<LayerVariant, LayerSize>;
  "color-picker": RoundedElevatedDefaults<FieldVariant, LayerSize>;
  modal: RoundedElevatedDefaults<
    "surface" | "solid" | "outline" | "soft" | "glass",
    LayerSize | "full"
  >;
  textarea: RoundedDefaults<FieldVariant, FieldSize>;
  breadcrumb: Defaults<never, "sm" | "md">;
  link: RoundedElevatedDefaults<"text" | "solid" | "outline", LayerSize>;
  badge: RoundedDefaults<"solid" | "soft" | "outline" | "glass", LayerSize>;
  card: Omit<
    RoundedElevatedDefaults<
      "surface" | "elevated" | "muted" | "outline" | "soft" | "glass",
      LayerSize,
      { padding?: "none" | "sm" | "md" | "lg" }
    >,
    "shadow"
  > & { shadow?: ThemeShadow | boolean };
  select: RoundedElevatedDefaults<FieldVariant, FieldSize>;
  autocomplete: RoundedElevatedDefaults<FieldVariant, FieldSize>;
  checkbox: RoundedDefaults<FieldVariant, LayerSize>;
  switch: RoundedDefaults<FieldVariant, LayerSize>;
  toggle: RoundedElevatedDefaults<ActionVariant, "sm" | "md" | "lg" | "xl">;
  "toggle-group": RoundedElevatedDefaults<ActionVariant, "sm" | "md" | "lg" | "xl">;
  collapsible: RoundedElevatedDefaults<"underline" | LayerVariant, LayerSize>;
  accordion: RoundedElevatedDefaults<"underline" | LayerVariant, LayerSize>;
  kbd: RoundedElevatedDefaults<"raised" | "outline" | "soft", LayerSize>;
  avatar: Defaults<never, "sm" | "md" | "lg" | "xl", {
    shape?: "circle" | "rounded" | "square";
  }>;
  pagination: RoundedDefaults<never, LayerSize>;
  resizable: RoundedElevatedDefaults<SurfaceVariant, LayerSize>;
  "scroll-area": RoundedElevatedDefaults<never, "thin" | "regular">;
  preview: Defaults;
  carousel: RoundedElevatedDefaults<SurfaceVariant>;
  sidebar: RoundedElevatedDefaults<SurfaceVariant>;
  attachment: RoundedElevatedDefaults<never, LayerSize>;
  table: RoundedElevatedDefaults<SurfaceVariant, never, {
    density?: "compact" | "default" | "comfortable";
  }>;
  calendar: RoundedElevatedDefaults;
  "date-picker": RoundedDefaults;
  "data-table": RoundedDefaults<SurfaceVariant, never, {
    density?: "compact" | "default" | "comfortable";
  }>;
  charts: RoundedDefaults;
  separator: Defaults<"solid" | "dashed" | "dotted", LayerSize>;
  skeleton: RoundedDefaults<"muted" | "soft" | "glass", LayerSize, {
    shape?: "text" | "rect" | "circle";
  }>;
  spinner: Defaults<never, "xs" | "sm" | "md" | "lg" | "xl">;
  progress: RoundedDefaults<"solid" | "soft" | "striped", LayerSize>;
  alert: RoundedElevatedDefaults<"surface" | "outline" | "soft" | "solid" | "glass", LayerSize>;
  toast: RoundedElevatedDefaults<"surface" | "soft" | "outline" | "glass", LayerSize>;
  tabs: RoundedElevatedDefaults<SurfaceVariant, LayerSize, {
    type?: "segmented" | "underline" | "pills" | "tiles";
    panelSurface?: boolean;
  }>;
  "code-block": RoundedElevatedDefaults<never, LayerSize>;
  "gradient-background": Defaults;
  dropdown: RoundedElevatedDefaults<SurfaceVariant>;
  navbar: ElevatedDefaults<SurfaceVariant, never, {
    type?: "bar" | "floating" | "minimal";
  }>;
  footer: Defaults;
}

import {
  computed,
  inject,
  provide,
  type ComputedRef,
  type InjectionKey,
  type MaybeRefOrGetter,
  toValue,
} from "vue";
import {
  defaultDesignTheme,
  isDesignTheme,
  resolveTheme,
  themePresentation,
  type DesignTheme,
  type ResolvedThemeDefinition,
  type ThemeComponentName,
  type ThemeFamily,
  type ThemeInput,
  type ThemePresentation,
  type ThemeVisualDefaults,
} from "./theme";

export interface BalsaThemeContext {
  input: ComputedRef<ThemeInput>;
  resolved: ComputedRef<ResolvedThemeDefinition>;
}

export const balsaThemeContextKey: InjectionKey<BalsaThemeContext> =
  Symbol("balsa-theme-context");

function createThemeContext(input: ComputedRef<ThemeInput>): BalsaThemeContext {
  return {
    input,
    resolved: computed(() => resolveTheme(input.value)),
  };
}

export function provideBalsaTheme(
  input: MaybeRefOrGetter<ThemeInput>,
): BalsaThemeContext {
  const context = createThemeContext(computed(() => toValue(input)));
  provide(balsaThemeContextKey, context);
  return context;
}

export function useBalsaThemeContext(): BalsaThemeContext | undefined {
  return inject(balsaThemeContextKey, undefined);
}

export interface ComponentThemeResolver {
  input: ComputedRef<ThemeInput>;
  resolved: ComputedRef<ResolvedThemeDefinition>;
  presentation: ComputedRef<ThemePresentation>;
  explicitPresentation: ComputedRef<ThemePresentation | undefined>;
  defaults: ComputedRef<ThemeVisualDefaults>;
  inheritedFromContext: boolean;
  presentationForPortal(boundary?: Element | null): ThemePresentation;
  resolve<T>(
    key: keyof ThemeVisualDefaults,
    explicitValue: T | undefined,
    fallback: T,
  ): T;
}

export function useComponentTheme(
  component: ThemeComponentName,
  family: ThemeFamily,
  explicitTheme: MaybeRefOrGetter<ThemeInput | undefined>,
): ComponentThemeResolver {
  const parent = useBalsaThemeContext();
  const input = computed<ThemeInput>(() =>
    toValue(explicitTheme) ?? parent?.input.value ?? defaultDesignTheme
  );
  const context = createThemeContext(input);
  provide(balsaThemeContextKey, context);

  const presentation = computed(() => themePresentation(input.value));
  const explicitPresentation = computed(() =>
    toValue(explicitTheme) === undefined ? undefined : presentation.value
  );
  const defaults = computed<ThemeVisualDefaults>(() => ({
    ...context.resolved.value.defaults.families?.[family],
    ...context.resolved.value.defaults.components?.[component],
  }));

  return {
    input,
    resolved: context.resolved,
    presentation,
    explicitPresentation,
    defaults,
    inheritedFromContext: Boolean(parent),
    presentationForPortal(boundary?: Element | null): ThemePresentation {
      if (toValue(explicitTheme) !== undefined || parent) return presentation.value;
      const host = boundary?.parentElement ?? boundary;
      const themedAncestor = host?.closest<HTMLElement>(
        "[data-theme], [data-theme-base]",
      );
      const legacyTheme = themedAncestor?.dataset.themeBase
        ?? themedAncestor?.dataset.theme;
      return isDesignTheme(legacyTheme)
        ? themePresentation(legacyTheme)
        : presentation.value;
    },
    resolve<T>(
      key: keyof ThemeVisualDefaults,
      explicitValue: T | undefined,
      fallback: T,
    ): T {
      if (explicitValue !== undefined) return explicitValue;
      const configured = defaults.value[key];
      return configured === undefined ? fallback : configured as T;
    },
  };
}

export function useResolvedThemeProps<
  P extends { theme?: ThemeInput },
  F extends Partial<Record<keyof ThemeVisualDefaults, unknown>>,
>(
  component: ThemeComponentName,
  family: ThemeFamily,
  rawProps: P,
  fallbacks: F,
): {
  props: { [K in keyof P]: K extends keyof F ? Exclude<P[K], undefined> : P[K] };
  theme: ComponentThemeResolver;
} {
  const theme = useComponentTheme(component, family, () => rawProps.theme);
  const props = new Proxy(rawProps, {
    get(target, property, receiver) {
      const explicit = Reflect.get(target, property, receiver);
      if (explicit !== undefined) return explicit;
      if (typeof property !== "string" || !(property in fallbacks)) return explicit;
      const configured = theme.defaults.value[property as keyof ThemeVisualDefaults];
      return configured ?? fallbacks[property as keyof F];
    },
  }) as { [K in keyof P]: K extends keyof F ? Exclude<P[K], undefined> : P[K] };

  return { props, theme };
}

export function inheritedThemeId(
  context: BalsaThemeContext | undefined,
): DesignTheme {
  const input = context?.input.value;
  if (isDesignTheme(input)) return input;
  return context?.resolved.value.base ?? defaultDesignTheme;
}

import {
  computed,
  reactive,
  readonly,
  ref,
  type App,
  type ComputedRef,
} from "vue";
import { balsaThemeContextKey } from "../components/ui/theme-context";
import {
  defaultDesignTheme,
  defineTheme,
  designThemes,
  isDesignTheme,
  normalizeThemeDefinition,
  resolveTheme,
  themePresentation,
  type ResolvedThemeDefinition,
  type DesignTheme,
  type ThemeOptions,
  type ThemeOverrides,
  type ThemePresentation,
  type ThemeDefinition,
  type ThemeInput,
} from "../components/ui/theme";

export const DESIGN_THEME_STORAGE_KEY = "balsa-ui-design-theme";

/**
 * The single editable theme slot. Built-in presets are never mutated: the first
 * edit copies the selected preset into this slot and selects it, and every later
 * edit overwrites the same slot.
 */
export const CUSTOM_DESIGN_THEME_ID = "balsa-custom";

export interface DesignThemeDraft {
  options?: ThemeOptions;
  overrides?: Pick<ThemeOverrides, "tokens">;
}

export interface CustomDesignTheme {
  /** The built-in preset this custom theme was branched from. */
  base: DesignTheme;
  draft: DesignThemeDraft;
}

export interface PersistedDesignThemeState {
  version: 5;
  selectedTheme: string;
  custom: CustomDesignTheme | null;
  appliedTheme: ThemePresentation;
}

export interface DesignThemeStoreOptions {
  root?: HTMLElement | null;
  storage?: Pick<Storage, "getItem" | "setItem" | "removeItem"> | null;
  themes?: readonly ThemeDefinition[];
  /**
   * Website/editor mode. Consumer applications should register source-controlled
   * definitions and leave this disabled so only the selected id is persisted.
   */
  persistDefinitions?: boolean;
  /**
   * Enables the editable custom-theme slot. Disabled by default so consumer
   * stores remain source-definition driven.
   */
  customTheme?: boolean;
}

function defaultState(): PersistedDesignThemeState {
  return {
    version: 5,
    selectedTheme: defaultDesignTheme,
    custom: null,
    appliedTheme: themePresentation(defaultDesignTheme),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function normalizeStoredThemeOptions(value: unknown): ThemeOptions | undefined {
  if (!isRecord(value)) return undefined;
  const border = value.border === "subtle" ? "medium" : value.border;
  return {
    ...value,
    ...(border === undefined ? {} : { border }),
  } as ThemeOptions;
}

export function normalizePersistedDesignThemeState(
  value: unknown,
  availableThemeIds: ReadonlySet<string> = new Set(
    designThemes.map(({ id }) => id),
  ),
): PersistedDesignThemeState {
  if (!isRecord(value) || value.version !== 5) return defaultState();
  const custom = normalizeCustomTheme(value.custom);
  const selectable = new Set<string>([
    ...availableThemeIds,
    ...(custom ? [CUSTOM_DESIGN_THEME_ID] : []),
  ]);
  const selectedTheme = typeof value.selectedTheme === "string"
    && selectable.has(value.selectedTheme)
    ? value.selectedTheme
    : defaultDesignTheme;

  return {
    version: 5,
    selectedTheme,
    custom,
    appliedTheme: themePresentation(
      selectedTheme === CUSTOM_DESIGN_THEME_ID && custom
        ? customThemeDefinition(custom)
        : isDesignTheme(selectedTheme) ? selectedTheme : defaultDesignTheme,
    ),
  };
}

function hasDraft(draft: DesignThemeDraft): boolean {
  return Boolean(
    (draft.options && Object.keys(draft.options).length)
    || (draft.overrides?.tokens && Object.keys(draft.overrides.tokens).length),
  );
}

function customThemeDefinition(custom: CustomDesignTheme): ThemeDefinition {
  return defineTheme({
    id: CUSTOM_DESIGN_THEME_ID,
    name: "Custom",
    extends: custom.base,
    ...custom.draft,
  });
}

function normalizeDraft(value: unknown, base: DesignTheme): DesignThemeDraft {
  if (!isRecord(value)) return {};
  try {
    const normalized = normalizeThemeDefinition({
      id: CUSTOM_DESIGN_THEME_ID,
      name: "Custom",
      extends: base,
      options: normalizeStoredThemeOptions(value.options),
      overrides: isRecord(value.overrides)
        ? value.overrides as ThemeOverrides
        : undefined,
    });
    return {
      ...(normalized.options ? { options: normalized.options } : {}),
      ...(normalized.overrides?.tokens
        ? { overrides: { tokens: normalized.overrides.tokens } }
        : {}),
    };
  } catch {
    return {};
  }
}

function normalizeCustomTheme(value: unknown): CustomDesignTheme | null {
  if (!isRecord(value)) return null;
  const base = isDesignTheme(value.base) ? value.base : defaultDesignTheme;
  const draft = normalizeDraft(value.draft, base);
  return hasDraft(draft) ? { base, draft } : null;
}

function readPersistedValue(
  storage: DesignThemeStoreOptions["storage"],
): unknown {
  if (!storage) return undefined;
  try {
    const value = storage.getItem(DESIGN_THEME_STORAGE_KEY);
    return value ? JSON.parse(value) : undefined;
  } catch {
    return undefined;
  }
}

function persistedDefinitions(value: unknown): ThemeDefinition[] {
  if (!isRecord(value) || !Array.isArray(value.customThemes)) return [];
  const definitions: ThemeDefinition[] = [];
  for (const candidate of value.customThemes) {
    try {
      if (!isRecord(candidate)) continue;
      const definition = normalizeThemeDefinition(
        defineTheme(candidate as unknown as ThemeDefinition),
      );
      if (!isDesignTheme(definition.id)) definitions.push(definition);
    } catch {
      // A malformed authored definition is ignored without invalidating the rest.
    }
  }
  return definitions;
}

export function createDesignThemeStore(options: DesignThemeStoreOptions = {}) {
  const root = options.root === undefined
    ? (typeof document === "undefined" ? null : document.documentElement)
    : options.root;
  const storage = options.storage === undefined
    ? (typeof window === "undefined" ? null : window.localStorage)
    : options.storage;
  const definitions = reactive(new Map<string, ThemeDefinition>());
  const persistedValue = readPersistedValue(storage);

  const initialDefinitions = [
    ...(options.themes ?? []),
    ...(options.persistDefinitions ? persistedDefinitions(persistedValue) : []),
  ];
  for (const definition of initialDefinitions) {
    const normalized = normalizeThemeDefinition(definition);
    if (isDesignTheme(normalized.id)) {
      throw new TypeError(`Custom theme id "${normalized.id}" conflicts with a built-in theme.`);
    }
    definitions.set(normalized.id, normalized);
  }

  const availableThemeIds = new Set<string>([
    ...designThemes.map(({ id }) => id),
    ...definitions.keys(),
  ]);
  const state = reactive(
    normalizePersistedDesignThemeState(persistedValue, availableThemeIds),
  ) as PersistedDesignThemeState;
  if (!options.customTheme) {
    state.custom = null;
    if (state.selectedTheme === CUSTOM_DESIGN_THEME_ID) {
      state.selectedTheme = defaultDesignTheme;
    }
  }
  const appliedVariables = new Set<string>();
  /**
   * A theme applied to the document without being selected or persisted, for a
   * route that presents themes it does not own. The visitor's own selection
   * returns when the preview is cleared or any editor writes to the store.
   */
  const preview = ref<ThemeInput | null>(null);

  const previewActive = computed(() => preview.value !== null);
  const customTheme = computed<CustomDesignTheme | null>(() => state.custom);
  const customThemeActive = computed(() =>
    state.selectedTheme === CUSTOM_DESIGN_THEME_ID && state.custom !== null
  );
  const activeTheme = computed<ThemeInput>(() => {
    if (preview.value) return preview.value;
    if (customThemeActive.value && state.custom) return customThemeDefinition(state.custom);
    if (isDesignTheme(state.selectedTheme)) return state.selectedTheme;
    return definitions.get(state.selectedTheme) ?? defaultDesignTheme;
  });
  const activeDefinition = computed<ResolvedThemeDefinition>(() =>
    resolveTheme(activeTheme.value)
  );
  const activeThemeName = computed(() => activeDefinition.value.name);
  const registeredThemes = computed(() => [...definitions.values()]);
  /** The draft the editor writes to: the custom slot, or the selected preset's empty starting point. */
  const activeDraft = computed<DesignThemeDraft | null>(() => {
    if (customThemeActive.value && state.custom) return state.custom.draft;
    return isDesignTheme(state.selectedTheme) ? {} : null;
  });
  /** The preset a custom theme was branched from, or the selected preset itself. */
  const activeBase = computed<DesignTheme>(() => {
    if (customThemeActive.value && state.custom) return state.custom.base;
    return isDesignTheme(state.selectedTheme) ? state.selectedTheme : defaultDesignTheme;
  });

  function apply(): void {
    if (!root) return;
    const presentation = themePresentation(activeTheme.value);
    root.dataset.theme = presentation.id;
    if (presentation.base) root.dataset.themeBase = presentation.base;
    else delete root.dataset.themeBase;

    for (const variable of appliedVariables) root.style.removeProperty(variable);
    appliedVariables.clear();
    for (const [variable, value] of Object.entries(presentation.style)) {
      root.style.setProperty(variable, value);
      appliedVariables.add(variable);
    }
  }

  function persist(): void {
    if (!storage) return;
    try {
      state.appliedTheme = themePresentation(activeTheme.value);
      storage.setItem(DESIGN_THEME_STORAGE_KEY, JSON.stringify(
        options.persistDefinitions
          ? {
              ...state,
              customThemes: [...definitions.values()],
              appliedTheme: themePresentation(activeTheme.value),
            }
          : state,
      ));
    } catch {
      // Theme selection remains live when persistence is unavailable.
    }
  }

  /**
   * Editing is an explicit statement about the visitor's own theme, so it
   * always wins over a route preview rather than disappearing beneath one.
   */
  function commit(): void {
    preview.value = null;
    apply();
    persist();
  }

  /** Applies a theme to the document without selecting or persisting it. */
  function setThemePreview(value: ThemeInput | null): void {
    preview.value = value;
    apply();
  }

  function hasTheme(id: string): boolean {
    if (id === CUSTOM_DESIGN_THEME_ID) return state.custom !== null;
    return isDesignTheme(id) || definitions.has(id);
  }

  function selectTheme(theme: string | ThemeDefinition): void {
    const id = typeof theme === "string" ? theme : theme.id;
    if (typeof theme !== "string" && !definitions.has(theme.id)) {
      registerTheme(theme);
    }
    if (!hasTheme(id)) return;
    state.selectedTheme = id;
    commit();
  }

  function registerTheme(definition: ThemeDefinition): void {
    const normalized = normalizeThemeDefinition(defineTheme(definition));
    if (isDesignTheme(normalized.id)) {
      throw new TypeError(`Custom theme id "${normalized.id}" conflicts with a built-in theme.`);
    }
    definitions.set(normalized.id, normalized);
    if (state.selectedTheme === normalized.id) commit();
    else persist();
  }

  function unregisterTheme(id: string): void {
    if (!definitions.delete(id)) return;
    if (state.selectedTheme === id) {
      state.selectedTheme = defaultDesignTheme;
      commit();
    } else persist();
  }

  function resetTheme(): void {
    preview.value = null;
    state.selectedTheme = defaultDesignTheme;
    state.custom = null;
    if (options.persistDefinitions) {
      commit();
      return;
    }
    try {
      storage?.removeItem(DESIGN_THEME_STORAGE_KEY);
    } catch {
      // The in-memory default remains authoritative for this session.
    }
    apply();
  }

  /**
   * Writes the editable slot. The first edit on a built-in preset branches it
   * into the custom theme and selects that; later edits overwrite the same slot,
   * so presets never accumulate hidden modifications.
   */
  function setCustomDraft(draft: DesignThemeDraft): void {
    if (!options.customTheme) return;
    const base = activeBase.value;
    const normalized = normalizeDraft(draft, base);
    if (!hasDraft(normalized)) {
      clearCustomTheme();
      return;
    }
    state.custom = { base, draft: normalized };
    state.selectedTheme = CUSTOM_DESIGN_THEME_ID;
    commit();
  }

  /** Discards the custom theme and returns to the preset it branched from. */
  function clearCustomTheme(): void {
    if (!options.customTheme || !state.custom) return;
    const base = state.custom.base;
    state.custom = null;
    if (state.selectedTheme === CUSTOM_DESIGN_THEME_ID) state.selectedTheme = base;
    commit();
  }

  const contextInput: ComputedRef<ThemeInput> = computed(() => activeTheme.value);
  const contextResolved = computed(() => activeDefinition.value);

  function install(app: App): void {
    app.provide(balsaThemeContextKey, {
      input: contextInput,
      resolved: contextResolved,
    });
  }

  apply();
  persist();

  return {
    state: readonly(state),
    activeTheme: readonly(activeTheme),
    activeDefinition: readonly(activeDefinition),
    activeThemeName: readonly(activeThemeName),
    activeDraft: readonly(activeDraft),
    activeBase: readonly(activeBase),
    customTheme: readonly(customTheme),
    customThemeActive: readonly(customThemeActive),
    registeredThemes: readonly(registeredThemes),
    previewActive: readonly(previewActive),
    setThemePreview,
    hasTheme,
    selectTheme,
    registerTheme,
    unregisterTheme,
    setCustomDraft,
    clearCustomTheme,
    resetTheme,
    install,
  };
}

let singleton: ReturnType<typeof createDesignThemeStore> | undefined;

export function useDesignThemeStore(options?: DesignThemeStoreOptions) {
  singleton ??= createDesignThemeStore(options);
  return singleton;
}
